int set_ext_regs_for_child(struct task_struct *child, void __user *uregs)
{
    struct thread_info *thread = &child->thread;
    struct user_regs_struct *regs = &thread->regs;
    int ret;

    if (!access_ok(uregs, sizeof(struct user_ext_regs)))
        return -EFAULT;

    flush_and_release_coprocessors();

    ret = copy_from_user(&thread->ext_regs, uregs, sizeof(struct user_ext_regs));
    if (ret)
        return -EFAULT;

    /* Copy relevant extended register values into the register structure */
    regs->cr0 = thread->ext_regs.cr0;
    regs->cr2 = thread->ext_regs.cr2;
    regs->cr3 = thread->ext_regs.cr3;
    regs->cr4 = thread->ext_regs.cr4;

    return 0;
}

int set_ext_regs(struct task_struct *child, void __user *uregs) {
    if (!access_ok(uregs, sizeof(struct user_regset)))
        return -EFAULT;

    flush_and_release_coprocessors();

    if (copy_from_user(&child->thread.ext_regs, uregs, sizeof(child->thread.ext_regs)))
        return -EFAULT;

    return 0;
}

int set_ext_regs_for_child(struct task_struct *child, void __user *uregs)
{
    if (!access_ok(uregs, sizeof(struct user_i387_struct)))
        return -EFAULT;

    /* Flush and release coprocessors if applicable */
    __flush_fpu();

    if (copy_from_user(&child->thread.i387, uregs, sizeof(struct user_i387_struct))) {
        return -EFAULT;
    }

    return 0;
}

